+ bool Scheduler::TryPrefill(const Request& r) {
+   auto slab = ClassifySlab(r.tokens);
+   if (slab_occupancy_[slab] >= slab_caps_[slab]) {
+     ApplySoftBackpressure(r);
+     return false;
+   }
+   slab_occupancy_[slab] += r.tokens;
+   epoch_coalescer_.Enqueue(slab, r);
+   return true;
+}
